-- game.types on an EMPTY registry, the only registry ShroudForge's own mod runtime can be given in a local
-- differential test (not published). Argument casts, raised texts and nil/reason tuples are registry-independent; the
-- registry-backed behaviour is covered by source-derived host tests (m6_types.rs).
local t = game.types
local keys = {}
for k, v in pairs(t) do keys[#keys + 1] = k .. ":" .. type(v) end
table.sort(keys)
T.value("keys", table.concat(keys, ","))
T.value("count", t.count)
T.value("version", t.version)
T.call("get.nil", t.get)
T.call("get.missing", t.get, "m6.Root")
T.call("get.number", t.get, 4242)
T.call("get.float", t.get, 4242.5)
T.call("get.table", t.get, {})
T.call("get_by_qualified_name.bool", t.get_by_qualified_name, true)
T.call("get_by_impact_name.missing", t.get_by_impact_name, "M6_Root")
T.call("get_by_qualified_hash.missing", t.get_by_qualified_hash, 1)
T.call("get_by_qualified_hash.negative", t.get_by_qualified_hash, -1)
T.call("get_by_qualified_hash.big", t.get_by_qualified_hash, 4294967296)
T.call("get_by_qualified_hash.fraction", t.get_by_qualified_hash, 1.5)
T.call("get_by_qualified_hash.float", t.get_by_qualified_hash, 7.0)
T.call("get_by_qualified_hash.string", t.get_by_qualified_hash, "7")
T.call("get_by_qualified_hash.text", t.get_by_qualified_hash, "seven")
T.call("get_by_internal_hash.nil", t.get_by_internal_hash)
T.call("get_by_internal_hash.missing", t.get_by_internal_hash, 0x77)
T.call("get_all", t.get_all)
T.call("get_all.false", t.get_all, false)
T.call("get_all.number", t.get_all, 0)
T.call("resolve.name", t.resolve, "m6.Nope")
T.call("resolve.hash", t.resolve, 1)
T.call("resolve.float", t.resolve, 1.0)
T.call("resolve.negative", t.resolve, -1)
T.call("resolve.big", t.resolve, 4294967296)
T.call("resolve.table", t.resolve, {hash = 1, domain = "internal"})
T.call("resolve.domain", t.resolve, {hash = 1, domain = "address"})
T.call("resolve.nodomain", t.resolve, {hash = 1})
T.call("resolve.nohash", t.resolve, {domain = "qualified"})
T.call("resolve.badhash", t.resolve, {hash = -1, domain = "qualified"})
T.call("resolve.bool", t.resolve, true)
T.call("resolve.nil", t.resolve)
T.call("find_by_hash", t.find_by_hash, 1)
T.call("find_by_hash.internal", t.find_by_hash, 1, "internal")
T.call("find_by_hash.domain", t.find_by_hash, 1, "address")
T.call("find_by_hash.bool", t.find_by_hash, 1, false)
T.call("find_by_hash.nil", t.find_by_hash)
T.call("get_by_index", t.get_by_index, 0)
T.call("get_by_index.negative", t.get_by_index, -1)
T.call("get_by_index.negative_float", t.get_by_index, -1.0)
T.call("get_by_index.fraction", t.get_by_index, 1.5)
T.call("get_by_index.text", t.get_by_index, "x")
T.call("find", t.find)
T.call("find.options", t.find, {prefix = "m6", attribute = "x", primitive_type = "Struct", has_ds = true})
T.call("find.number_prefix", t.find, {prefix = 42, has_ds = 0})
T.call("find.string", t.find, "m6")
T.call("of.nil", t.of)
T.call("of.table", t.of, {})
T.call("of.number", t.of, 1)
T.call("of.string", t.of, "m6.Root")
